import {type MouseEventHandler, useState} from "react";

interface Entry {
  id: string;
  label: string;
}

export const EntriesPage = ({entries}: {entries: Entry[]}) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  /**
   * @event 선택 항목 토글 처리
   */
  const handleSelectionToggle = (entryId: string): MouseEventHandler<HTMLButtonElement> => (_event) => {
    setSelectedIds((currentSelectedIds) =>
      currentSelectedIds.includes(entryId)
        ? currentSelectedIds.filter((selectedId) => selectedId !== entryId)
        : [...currentSelectedIds, entryId],
    );
  };

  return (
    <section>
      <p>{selectedIds.length > 0 ? `${selectedIds.length} selected` : "No selection"}</p>
      {entries.map((entry) => (
        <button key={entry.id} onClick={handleSelectionToggle(entry.id)}>
          {entry.label}
        </button>
      ))}
    </section>
  );
};
